
const state={user:null,page:localStorage.getItem('PMA_CURRENT_PAGE')||'home',market:localStorage.getItem('PMA_MARKET')||'Forex',symbol:localStorage.getItem('PMA_SYMBOL')||'EURUSD',ref:new URLSearchParams(location.search).get('ref')||'',notif:[],scannerTimer:null,entryTimer:null,dayTradeTimer:null,notifTimer:null,browserAlertsReady:false,serverVerified:false,restoringReload:false,notificationCategory:'All',scannerStyle:localStorage.getItem('PMA_SCANNER_STYLE')||'Scalping',scannerTf:localStorage.getItem('PMA_SCANNER_TF')||'5m',scannerLock:null,lastTrends:null};
const markets={Forex:['EURUSD','GBPUSD','USDJPY','GBPJPY','AUDUSD','USDCAD','USDCHF','NZDUSD','EURJPY','EURGBP','EURCHF','GBPCHF','AUDJPY','CADJPY'],Indices:['US30','NAS100','SPX500','GER40','UK100','FRA40','JP225'],Metals:['XAUUSD','XAGUSD','XPTUSD','XPDUSD'],Crypto:['BTCUSD','ETHUSD','SOLUSD','XRPUSD','LTCUSD'],Commodities:['USOIL','UKOIL','NATGAS','COPPER']};
const API_BASE=(localStorage.getItem('PMA_API_BASE')||'https://pips-master-frontend.onrender.com').replace(/\/$/,'');
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};const token=localStorage.getItem('PMA_TOKEN');if(token)headers.Authorization='Bearer '+token;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(API_BASE+'/api'+path,{...opts,headers,signal:controller.signal,cache:'no-store'});const x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.detail||'Request failed');return x}catch(e){if(e?.name==='AbortError')throw Error('Please try again in a moment.');if(e instanceof TypeError)throw Error('Please try again in a moment.');throw e}finally{clearTimeout(timer)}}
function show(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(id).classList.add('active');if(id==='signup'&&state.ref){suMsg.textContent='Referral code: '+state.ref;suMsg.className='form-msg ok'}if(id==='app')page(state.page||'home',true)}
function applyTheme(){const theme=localStorage.getItem('PMA_THEME')||'dark';document.body.classList.toggle('light',theme==='light');const b=document.getElementById('themeToggle');if(b){b.innerHTML=theme==='light'?'<span class="theme-icon" aria-hidden="true">☀️</span><span>Light mode</span>':'<span class="theme-icon" aria-hidden="true">🌙</span><span>Dark mode</span>';b.setAttribute('aria-label','Switch to '+(theme==='light'?'dark':'light')+' mode');}}
function toggleTheme(){const next=(localStorage.getItem('PMA_THEME')||'dark')==='light'?'dark':'light';localStorage.setItem('PMA_THEME',next);applyTheme()}

function togglePassword(id,btn){const el=document.getElementById(id);el.type=el.type==='password'?'text':'password';btn.textContent=el.type==='password'?'👁️':'🙈'}
function validateSignup(){if(!document.getElementById('suPass'))return;const p=suPass.value,p2=suPass2.value;suPassMsg.textContent=p.length===0?'':'Password must be at least 8 characters.';suPassMsg.className='form-msg '+(p.length>=8?'ok':'error');suMatchMsg.textContent=p2.length===0?'':(p===p2?'Passwords match.':'Passwords do not match.');suMatchMsg.className='form-msg '+(p2.length===0?'':(p===p2?'ok':'error'))}
function saveLocalUser(u){localStorage.setItem('PMA_LOCAL_USER',JSON.stringify(u));state.user=u;localStorage.setItem('PMA_USER_PROFILE',JSON.stringify(u))}
function readJson(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function addNotification(title,text,type='info',targetPage=''){const n={id:Date.now()+Math.random(),title,text,type,target_page:targetPage||notificationTarget({type}),time:new Date().toLocaleString(),read:false};const history=readJson('PMA_NOTIFICATION_HISTORY',[]);history.unshift(n);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history.slice(0,250)));const inbox=readJson('PMA_NOTIFICATION_INBOX',[]);inbox.unshift(n);localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox.slice(0,60)));state.notif=history;updateNotifBadge()}
function migrateNotifications(){const old=readJson('PMA_NOTIFICATIONS',[]);if(old.length&&!localStorage.getItem('PMA_NOTIFICATION_HISTORY')){localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(old));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(old));}}
function getNotificationHistory(){migrateNotifications();return readJson('PMA_NOTIFICATION_HISTORY',[])}
function getNotificationInbox(){migrateNotifications();return readJson('PMA_NOTIFICATION_INBOX',[])}
function updateNotifBadge(){const dismissed=new Set(readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]).map(String));const n=getNotificationHistory().filter(x=>!dismissed.has(String(x.server_id||x.id))&&!x.read);const b=document.getElementById('notifBadge');if(b)b.textContent=String(n.length)}
function loadLocalUser(){try{return JSON.parse(localStorage.getItem('PMA_LOCAL_USER')||'null')}catch{return null}}
async function signup(){validateSignup();if(!suUser.value.trim()||!suName.value.trim()||!suEmail.value.trim()){suMsg.textContent='Please complete all required fields.';suMsg.className='form-msg error';return}if(suPass.value.length<8||suPass.value!==suPass2.value){suMsg.textContent=suPass.value!==suPass2.value?'Passwords do not match.':'Please fix the password above.';suMsg.className='form-msg error';return}suMsg.textContent='Creating your account…';suMsg.className='form-msg ok';try{const x=await apiRetry('/auth/signup',{method:'POST',body:JSON.stringify({username:suUser.value,full_name:suName.value,email:suEmail.value.trim().toLowerCase(),password:suPass.value,confirm_password:suPass2.value,referral:state.ref})},2);state.user=x.user;state.serverVerified=true;localStorage.setItem('PMA_TOKEN',x.token||'');saveLocalUser(x.user);addNotification('Welcome to Pips Master Academy','Your account was created successfully.','account');enterApp(true)}catch(e){suMsg.textContent=e?.message||'The PMA server could not create your account. Please try again.';suMsg.className='form-msg error'}}
async function login(){const email=liEmail.value.trim().toLowerCase(),pass=liPass.value;if(!email||!pass){liMsg.textContent='Enter your email and password.';liMsg.className='form-msg error';return}liMsg.textContent='Connecting to PMA…';liMsg.className='form-msg ok';try{const x=await apiRetry('/auth/login',{method:'POST',body:JSON.stringify({email,password:pass})},2);state.user=x.user;state.serverVerified=true;localStorage.setItem('PMA_TOKEN',x.token||'');saveLocalUser(x.user);addNotification('Welcome back','You successfully logged in.','security');enterApp(true);return}catch(e){liMsg.textContent=e?.message||'Login failed. Check your email and password, then try again.';liMsg.className='form-msg error'}}
function apiRetry(path,opts={},retries=2){let attempt=0;const run=()=>api(path,opts).catch(e=>{if(attempt++<retries)return new Promise(r=>setTimeout(r,1200*(attempt))).then(run);throw e});return run()}
function enterApp(resetPage=false){show('app');userMini.textContent='@'+state.user.username;if(resetPage){state.page='home';localStorage.setItem('PMA_CURRENT_PAGE','home');localStorage.removeItem('PMA_SCROLL_HOME')}page(state.page||'home',!resetPage);syncBackendProfile();syncBackendNotifications();startNotificationPolling()}
function closeMenu(){document.getElementById('side').classList.remove('open')}
function page(p,restore=false){if(p==='admin')p='profile';if(state.page&&state.page!==p){const old=document.getElementById('screen');if(old)localStorage.setItem('PMA_SCROLL_'+state.page,String(old.scrollTop||0))}state.page=p;localStorage.setItem('PMA_CURRENT_PAGE',p);localStorage.setItem('PMA_MARKET',state.market);localStorage.setItem('PMA_SYMBOL',state.symbol);closeMenu();pageTitle.textContent=p==='profile'?'My Profile':p[0].toUpperCase()+p.slice(1);const s=document.getElementById('screen');const views={home,signals,daytrade,calculator,progress,referrals,community,profile,feedback,notifications,about};s.innerHTML=(views[p]||home)();if(p==='calculator')setCalcTab('risk');if(state.page!=='signals')clearInterval(state.scannerTimer);if(state.page!=='daytrade')clearInterval(state.dayTradeTimer);if(p==='signals')startScanner();if(p==='daytrade')startDayTrade();if(p==='home')loadHomeProgress();if(p==='progress')loadProgress();if(p==='referrals')loadReferrals();if(p==='community')loadMessages();if(p==='profile'&&state.serverVerified&&state.user?.role==='admin')requestAnimationFrame(loadAdminStats);if(p==='feedback')loadMyFeedback();if(p==='notifications')loadNotificationsPage();requestAnimationFrame(()=>{s.scrollTop=restore?Number(localStorage.getItem('PMA_SCROLL_'+p)||0):0})}
function home(){return `<div class="section"><div class="home-hero"><div class="card"><div class="pill">PIPS MASTER ACADEMY</div><h1 class="section-title" style="font-size:46px;margin-top:18px">A complete space for the modern learner.</h1><p class="lead">Learn market structure, explore opportunities, manage risk and stay connected with a community built around disciplined decision-making.</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="btn" onclick="page('signals')">Explore Signals</button><button class="btn alt" onclick="page('about')">Explore Academy</button></div><div class="divider"></div><div class="statline"><span>Personal PMA ID</span><b>${state.user.pma_id}</b></div><div class="statline"><span>Account role</span><b>${state.user.role==='admin'?'Administrator':'Member'}</b></div></div><img class="home-hero-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85" alt="Global financial markets"></div><div id="homeProgressMini" class="home-mini-progress"><div class="home-mini-card"><div class="mini-label">Academy rank</div><div id="homeRank" class="mini-value">—</div><div id="homeRankSub" class="mini-sub">Loading</div></div><div class="home-mini-card"><div class="mini-label">Learning</div><div id="homeLearning" class="mini-value">—</div><div id="homeLearningSub" class="mini-sub">Progress</div></div><div class="home-mini-card"><div class="mini-label">Referrals</div><div id="homeReferral" class="mini-value">—</div><div id="homeReferralSub" class="mini-sub">This month</div></div><div class="home-mini-card"><div class="mini-label">Overall</div><div id="homeOverall" class="mini-value">—</div><div id="homeOverallSub" class="mini-sub">Academy progress</div></div></div><div class="photo-section"><div class="photo-grid"><article class="card photo-card"><img src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1400&q=85" alt="Trader analysing financial markets"><div class="photo-overlay"><h3>See the market, not just the numbers.</h3><p class="muted" style="margin:0">A more visual workspace for charts, market structure and disciplined planning.</p></div></article><article class="card photo-card"><img src="https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?auto=format&fit=crop&w=1000&q=85" alt="Financial market workspace"><div class="photo-overlay"><h3>Built around real market context.</h3><p class="muted" style="margin:0">Explore different market categories and live chart views.</p></div></article></div><div class="photo-grid-small"><article class="card"><img class="real-photo" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=900&q=85" alt="Market analysis screen"><h3 style="margin:12px 0 6px">Analysis</h3><p class="muted">Charts and structure in one place.</p></article><article class="card"><img class="real-photo" src="https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=900&q=85" alt="Planning and finance workspace"><h3 style="margin:12px 0 6px">Planning</h3><p class="muted">Think through the setup before acting.</p></article><article class="card"><img class="real-photo" src="https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=900&q=85" alt="Professional workspace"><h3 style="margin:12px 0 6px">Professional feel</h3><p class="muted">A cleaner, more mature academy experience.</p></article></div><div class="image-band"><img src="https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=900&q=85" alt="Professional team workspace"><img src="https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=900&q=85" alt="Team collaboration"><img src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&q=85" alt="Learning with technology"><img src="https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=900&q=85" alt="Business meeting"></div></div><div class="feature-grid"><div class="card"><img class="feature-img" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=1200&q=85" alt="Candlestick analysis"><h3>Market structure</h3><p class="muted">Study trends, support and resistance, supply and demand, momentum and confirmation in one organised workspace.</p></div><div class="card"><img class="feature-img" src="https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?auto=format&fit=crop&w=1200&q=85" alt="Trading dashboard"><h3>Opportunity scanning</h3><p class="muted">Select a market category and search symbols instead of being limited to a tiny fixed watchlist.</p></div><div class="card"><img class="feature-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85" alt="Financial chart"><h3>Risk first</h3><p class="muted">Use the calculator to understand risk before acting. A good process starts before an entry.</p></div></div><div class="split"><div class="card"><h2>Built for clarity</h2><p class="lead">The academy keeps important information in focused sections instead of putting everything into one crowded page. Your profile, signals, calculator, community and learning material each have their own workspace.</p><p class="muted">The website is designed to grow as more market-data, learning and community services are connected.</p></div><div class="card"><img class="mini-img" src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1200&q=85" alt="Trader workspace"><h3 style="margin-top:15px">One workspace. More structure.</h3><p class="muted">Follow your own learning process, keep your account information organised and explore market tools without unnecessary clutter.</p></div></div><div class="grid" style="margin-top:18px"><div class="card"><div class="muted">Market categories</div><div class="big">${Object.keys(markets).length}</div><p class="muted">Forex, indices, metals, crypto and commodities.</p></div><div class="card"><div class="muted">Searchable symbols</div><div class="big">${Object.values(markets).flat().length}+</div><p class="muted">Expandable as your data provider grows.</p></div><div class="card"><div class="muted">Community</div><div class="big">Live</div><p class="muted">Group conversation and official updates.</p></div><div class="card"><div class="muted">Profile control</div><div class="big">Editable</div><p class="muted">Personal details can be updated while account IDs remain protected.</p></div></div><div class="footer-note">Pips Master Academy • Learn first. Analyse clearly. Manage risk responsibly.</div></div>`}
function scannerTimeframes(style){return ['1m','5m','15m','1h','4h','1d']}
function setScannerPreference(style,tf){state.scannerStyle=style;state.scannerTf=tf;localStorage.setItem('PMA_SCANNER_STYLE',style);localStorage.setItem('PMA_SCANNER_TF',tf);state.scannerLock=null;state.lastTrends=null;renderScanner();scanMarket()}
function signals(){const tfs=scannerTimeframes(state.scannerStyle);if(!tfs.includes(state.scannerTf))state.scannerTf=tfs[0];return `<div class="section"><h1 class="section-title">Automated Market Scanner</h1><p class="lead">Choose how you want the scanner to analyse the selected market. Trigger timeframe is separate from the multi-timeframe context below.</p><div class="card"><div class="scanner-preferences"><div class="field"><label>Trading style</label><select id="scannerStyle" onchange="setScannerPreference(this.value,state.scannerTf)">${['Scalping','Day Trading','Swing Trading'].map(x=>`<option ${x===state.scannerStyle?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Scanner trigger timeframe</label><select id="scannerTf" onchange="setScannerPreference(state.scannerStyle,this.value)">${tfs.map(x=>`<option ${x===state.scannerTf?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="filters"><button class="btn alt" onclick="scanMarket()">↻ Refresh</button><button class="btn ghost" onclick="page('daytrade')">Open Day Trade</button></div><span id="scannerStatus" class="muted" style="display:block;margin-top:8px;font-size:12px">Checking market data…</span></div><div class="card"><div class="chips">${Object.keys(markets).map(x=>`<button class="chip ${state.market===x?'active':''}" onclick="state.market='${x}';state.symbol='';page('signals')">${x}</button>`).join('')}</div><div class="filters"><input id="symbolSearch" class="search" placeholder="Search a supported symbol, e.g. EURUSD, GBPUSD, XAUUSD" oninput="renderScanner()"><button class="btn alt" onclick="clearSymbolSearch()">Clear</button></div><div id="symbolResults" class="chips"></div></div><div class="card trend-panel"><h3>Multi-timeframe trend</h3><p class="muted">These cards provide market context; they are not the scanner trigger timeframe.</p><div id="trendGrid" class="trend-grid"></div></div><div class="card tv-wrap"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><b>TradingView Live Chart</b><div class="muted" id="tvSymbolLabel">${state.symbol||markets[state.market][0]}</div></div><span class="pill" id="tvTfLabel">${state.scannerTf}</span></div><iframe id="tvFrame" title="TradingView chart" allowtransparency="true" scrolling="no"></iframe></div><div id="scannerArea"></div><div class="card" style="margin-top:16px"><h3>Closest monitored setups</h3><p class="muted">Ranked by setup state and estimated travel to the next opposing zone.</p><div id="nearbySetups"></div></div></div>`}
function fmtDuration(mins){if(mins==null)return '—';const m=Math.max(0,Math.round(mins));if(m<60)return m+' min';const h=Math.floor(m/60),r=m%60;return h+'h'+(r?' '+r+'m':'')}
function formatEntryEta(c){return c?.candles_to_next_zone!=null?`≈ ${c.candles_to_next_zone} candles • ${fmtDuration(c.estimated_minutes_to_next_zone)}`:'Waiting for verified data…'}
function startScanner(){clearInterval(state.scannerTimer);renderScanner();scanMarket();state.scannerTimer=setInterval(scanMarket,30000)}
function clearSymbolSearch(){const el=document.getElementById('symbolSearch');if(el)el.value='';renderScanner()}
function renderScanner(){const area=document.getElementById('scannerArea');if(!area)return;const q=(document.getElementById('symbolSearch')?.value||'').toUpperCase();const syms=markets[state.market].filter(x=>x.includes(q));document.getElementById('symbolResults').innerHTML=syms.map(x=>`<button class="chip ${state.symbol===x?'active':''}" onclick="state.symbol='${x}';renderScanner()">${x}</button>`).join('')||'<span class="muted">No matching supported symbol.</span>';const selected=state.symbol||syms[0]||markets[state.market][0];updateTradingView(selected);area.innerHTML=`<div class="card closest signal"><div class="pill">● PMA AUTOMATED SIGNAL ENGINE</div><div class="scanner-heading"><div><h2 id="selectedSymbol">${selected}</h2><div class="muted">${state.market}</div></div><div id="selectedDirection" class="signal-badge">WAITING</div></div><div id="selectedEta" class="eta">Connecting to verified market data…</div><p id="selectedZone" class="muted">Analysing trend, structure, supply/demand and support/resistance.</p><div id="selectedMeta" class="zone-badge">Verified data only</div><div id="selectedStats" class="scanner-stats"></div><div id="selectedDetails" class="scanner-details"></div></div>`;renderTrendGrid()}
function updateTradingView(symbol){const frame=document.getElementById('tvFrame');if(!frame)return;const tv=state.market==='Forex'?'FX:'+symbol:(state.market==='Indices'?'CAPITALCOM:'+symbol:(state.market==='Metals'?'OANDA:'+symbol:(state.market==='Crypto'?'COINBASE:'+symbol:'TVC:'+symbol)));const tvIntervals={'1m':'1','5m':'5','15m':'15','1h':'1H','4h':'4H','1d':'1D'};const interval=tvIntervals[state.scannerTf]||'5';document.getElementById('tvSymbolLabel').textContent=symbol;const tf=document.getElementById('tvTfLabel');if(tf)tf.textContent=state.scannerTf;frame.src='https://www.tradingview.com/widgetembed/?symbol='+encodeURIComponent(tv)+'&interval='+encodeURIComponent(interval)+'&hidesidetoolbar=1&symboledit=1&saveimage=0&toolbarbg=%23081118&hideideas=1&theme='+((localStorage.getItem('PMA_THEME')||'dark')==='light'?'light':'dark')+'&style=1&timezone=Etc%2FUTC'}
async function scanMarket(){
  const selected=state.symbol||markets[state.market][0];
  const statusEl=document.getElementById('scannerStatus');
  try{
    if(statusEl)statusEl.textContent='Loading verified market data…';
    const scanSymbols=[selected,...markets[state.market].filter(x=>x!==selected).slice(0,7)].join(',');
    const q=await apiRetry('/signals/scan?market='+encodeURIComponent(state.market)+'&symbols='+encodeURIComponent(scanSymbols)+'&timeframe='+encodeURIComponent(state.scannerTf));
    const c=(q.opportunities||[]).find(x=>x.symbol===selected)||q.closest;
    if(statusEl)statusEl.textContent=q.message||'Verified market data loaded.';
    if(!c){
      const eta=document.getElementById('selectedEta');
      const zone=document.getElementById('selectedZone');
      const meta=document.getElementById('selectedMeta');
      const stats=document.getElementById('selectedStats');
      const details=document.getElementById('selectedDetails');
      const dir=document.getElementById('selectedDirection');
      if(eta)eta.textContent='NO VERIFIED MARKET DATA';
      if(zone)zone.textContent=q.message||'No verified candle response.';
      if(meta)meta.textContent='No verified candle response • no signal generated';
      if(stats)stats.innerHTML='';
      if(details)details.innerHTML='';
      if(dir)dir.textContent='NO DATA';
      renderTrendGrid(state.lastTrends||{});
      renderNearby(q.opportunities||[]);
      return;
    }
    const dir=document.getElementById('selectedDirection');
    if(dir)dir.textContent=c.direction||'NO TRADE';
    const eta=document.getElementById('selectedEta');
    const zone=document.getElementById('selectedZone');
    const meta=document.getElementById('selectedMeta');
    const stats=document.getElementById('selectedStats');
    const details=document.getElementById('selectedDetails');
    if(eta)eta.textContent=formatEntryEta(c);
    if(zone)zone.textContent=c.next_zone!=null?`${c.direction} • next ${c.zone_type||'zone'} at ${c.next_zone} • ${c.pips_to_next_zone??'—'} pips away`:'Waiting for the next qualifying zone.';
    if(meta)meta.textContent=`${c.candles_to_next_zone??'—'} candles • ${fmtDuration(c.estimated_minutes_to_next_zone)} • ${c.status||'WATCHING'} • ${c.timeframe||state.scannerTf} • updated ${new Date(c.updated_at).toLocaleTimeString()}`;
    if(stats)stats.innerHTML='<span><b>'+((c.setup_strength??'—'))+'/100</b> setup strength</span><span><b>'+((c.trend_alignment||'—'))+'</b> trend alignment</span><span><b>'+((c.validation?.win_rate??'—'))+(c.validation?.win_rate!=null?'%':'')+'</b> historical validation</span><span><b>'+((c.validation?.samples??0))+'</b> samples</span>';
    if(details)details.innerHTML=`<div class="detail-grid"><div><small>Entry zone</small><b>${c.entry_zone??'—'}</b></div><div><small>Stop loss</small><b>${c.stop_loss??'—'}</b></div><div><small>TP1</small><b>${c.take_profit_1??'—'}</b></div><div><small>TP2</small><b>${c.take_profit_2??'—'}</b></div><div><small>Structure</small><b>${escapeHtml(c.structure||'—')}</b></div><div><small>Next signal</small><b>${escapeHtml(c.next_signal_status||'—')}</b></div><div><small>Trigger</small><b>${escapeHtml(c.next_signal_trigger||'—')}</b></div><div><small>RSI 15m</small><b>${c.rsi_15m??'—'}</b></div><div><small>Support</small><b>${c.support??'—'}</b></div><div><small>Resistance</small><b>${c.resistance??'—'}</b></div></div><div class="notice" style="margin-top:12px"><b>Why this setup:</b> ${escapeHtml((c.reasons||[]).join(' • ')||'Waiting for more confluence.')}</div>`;
    state.lastTrends=c.trends||state.lastTrends||{};
    renderTrendGrid(state.lastTrends);
    renderNearby(q.opportunities||[]);
    const key='PMA_LAST_SIGNAL_'+selected;
    const previous=localStorage.getItem(key);
    if(c.status==='SIGNAL READY'&&previous!==String(c.updated_at||'')){addNotification('New scanner setup',`${selected} has a ${c.direction} setup ready for confirmation.`,'signal');localStorage.setItem(key,String(c.updated_at||''))}
  }catch(e){
    if(statusEl)statusEl.textContent='Market data is temporarily unavailable — retrying automatically.';
    const eta=document.getElementById('selectedEta');
    const zone=document.getElementById('selectedZone');
    const meta=document.getElementById('selectedMeta');
    if(eta)eta.textContent='WAITING FOR VERIFIED DATA';
    if(zone)zone.textContent='The scanner will retry automatically without refreshing the page.';
    if(meta)meta.textContent='Feed temporarily unavailable • previous verified trend context retained';
    renderTrendGrid(state.lastTrends||{});
  }
}
function renderTrendGrid(trends={}){
  const el=document.getElementById('trendGrid');if(!el)return;
  const frames=[['15m','15 Minutes'],['30m','30 Minutes'],['1h','1 Hour'],['4h','4 Hours'],['1d','1 Day']];
  el.innerHTML=frames.map(([key,label])=>{const v=trends[key];const cls=v==='Bullish'?'bullish':v==='Bearish'?'bearish':v==='Neutral'?'neutral':'unavailable';return `<div class="trend-box ${cls}"><span>${label}</span><strong>${v||'Feed unavailable'}</strong><small>${v?'Verified candle analysis':'Waiting for verified candle response'}</small></div>`}).join('')
}
function renderNearby(items){const el=document.getElementById('nearbySetups');if(!el)return;if(!items.length){el.innerHTML='<p class="muted">No verified setups are available yet.</p>';return}el.innerHTML=items.slice(0,8).map(x=>`<div class="near-row"><div><div class="near-symbol">${x.symbol} • ${x.direction||'NO TRADE'}</div><div class="muted">${x.status||'WATCHING'} • next ${x.next_zone_type||'zone'} • ${x.pips_to_next_zone??'—'} pips • ${x.candles_to_next_zone??'—'} candles</div></div><div class="near-eta">${formatEntryEta(x)}</div></div>`).join('')}
function notifyNear(symbol,detail){if(window.Notification&&Notification.permission==='granted')new Notification('Pips Master Academy',{body:symbol+' is approaching its '+detail+' zone.'});toast(symbol+' is approaching its '+detail+' zone')}

function calculator(){return `<div class="section"><h1 class="section-title">Trading Calculator Hub</h1><p class="lead">Use the tools below with your own numbers. Broker specifications can differ, so treat results as estimates.</p><div class="calc-tabs"><button class="chip active" data-calc="risk" onclick="setCalcTab('risk')">Risk</button><button class="chip" data-calc="pnl" onclick="setCalcTab('pnl')">Profit / Loss</button><button class="chip" data-calc="pip" onclick="setCalcTab('pip')">Pip Value</button><button class="chip" data-calc="rr" onclick="setCalcTab('rr')">R:R</button><button class="chip" data-calc="margin" onclick="setCalcTab('margin')">Margin</button><button class="chip" data-calc="compound" onclick="setCalcTab('compound')">Compounding</button></div><div id="calcPanel" class="card"></div><div class="grid3" style="margin-top:18px"><div class="card"><h3>Risk</h3><p class="muted">Understand your planned risk before using an entry idea.</p></div><div class="card"><h3>Position size</h3><p class="muted">Position size depends on your stop distance and instrument value.</p></div><div class="card"><h3>Planning</h3><p class="muted">Use the calculator alongside the scanner instead of treating a signal as a guarantee.</p></div></div></div>`}
function setCalcTab(tab){document.querySelectorAll('[data-calc]').forEach(b=>b.classList.toggle('active',b.dataset.calc===tab));const panel=document.getElementById('calcPanel');if(!panel)return;const forms={risk:`<div class="grid"><div class="field"><label>Balance</label><input id="cBal" type="number" value="1000"></div><div class="field"><label>Risk %</label><input id="cRisk" type="number" value="1" step="0.1"></div><div class="field"><label>Stop distance (pips/points)</label><input id="cStop" type="number" value="20"></div><div class="field"><label>Value per pip/point per lot</label><input id="cPipVal" type="number" value="10"></div></div><button class="btn" onclick="runCalc('risk')">Calculate</button>`,pnl:`<div class="grid"><div class="field"><label>Entry</label><input id="pEntry" type="number" value="1.1000" step="0.0001"></div><div class="field"><label>Exit</label><input id="pExit" type="number" value="1.1050" step="0.0001"></div><div class="field"><label>Lot size</label><input id="pLot" type="number" value="0.10" step="0.01"></div><div class="field"><label>Value per pip/point per lot</label><input id="pPip" type="number" value="10"></div></div><button class="btn" onclick="runCalc('pnl')">Calculate</button>`,pip:`<div class="grid"><div class="field"><label>Lot size</label><input id="vLot" type="number" value="0.10" step="0.01"></div><div class="field"><label>Value per pip/point per lot</label><input id="vPip" type="number" value="10"></div></div><button class="btn" onclick="runCalc('pip')">Calculate</button>`,rr:`<div class="grid"><div class="field"><label>Entry</label><input id="rEntry" type="number" value="100"></div><div class="field"><label>Stop loss</label><input id="rSl" type="number" value="95"></div><div class="field"><label>Take profit</label><input id="rTp" type="number" value="110"></div></div><button class="btn" onclick="runCalc('rr')">Calculate</button>`,margin:`<div class="grid"><div class="field"><label>Units / contract size</label><input id="mUnits" type="number" value="100000"></div><div class="field"><label>Price</label><input id="mPrice" type="number" value="1.1000" step="0.0001"></div><div class="field"><label>Leverage</label><input id="mLev" type="number" value="100"></div></div><button class="btn" onclick="runCalc('margin')">Calculate</button>`,compound:`<div class="grid"><div class="field"><label>Starting balance</label><input id="coStart" type="number" value="1000"></div><div class="field"><label>Return per period %</label><input id="coRate" type="number" value="2" step="0.1"></div><div class="field"><label>Number of periods</label><input id="coPeriods" type="number" value="12"></div></div><button class="btn" onclick="runCalc('compound')">Calculate</button>`};panel.innerHTML=forms[tab]+'<div id="calcResult" style="margin-top:18px"></div>'}
function runCalc(kind){const out=document.getElementById('calcResult');if(!out)return;let html='';if(kind==='risk'){const risk=+cBal.value*(+cRisk.value/100),lot=risk/(Math.max(+cStop.value,1e-9)*Math.max(+cPipVal.value,1e-9));html=`<div class="notice">Risk amount: <b>${risk.toFixed(2)}</b><br>Estimated position size: <b>${lot.toFixed(3)}</b> lots`;}else if(kind==='pnl'){const pips=Math.abs(+pExit.value-+pEntry.value);const pnl=pips*(+pLot.value)*(+pPip.value);html=`<div class="notice">Price distance: <b>${pips.toFixed(5)}</b><br>Estimated P/L: <b>${pnl.toFixed(2)}</b> in the value unit you entered.`;}else if(kind==='pip'){const val=(+vLot.value)*(+vPip.value);html=`<div class="notice">Estimated pip/point value: <b>${val.toFixed(2)}</b>`;}else if(kind==='rr'){const risk=Math.abs(+rEntry.value-+rSl.value),reward=Math.abs(+rTp.value-+rEntry.value);html=`<div class="notice">Risk distance: <b>${risk.toFixed(5)}</b><br>Reward distance: <b>${reward.toFixed(5)}</b><br>Risk-to-reward: <b>1 : ${reward/Math.max(risk,1e-9).toFixed(2)}</b>`;}else if(kind==='margin'){const margin=(+mUnits.value*+mPrice.value)/Math.max(+mLev.value,1);html=`<div class="notice">Estimated margin: <b>${margin.toFixed(2)}</b><br><span class="muted">Actual margin depends on the broker and instrument contract rules.</span>`;}else{const projected=+coStart.value*Math.pow(1+(+coRate.value/100),Math.max(0,+coPeriods.value));html=`<div class="notice">Illustrative projected balance: <b>${projected.toFixed(2)}</b><br><span class="muted">This is a mathematical projection, not a promise of returns.</span>`;}out.innerHTML=html+'</div>'}
function daytrade(){const tfs=['1m','5m','15m','1h','4h','1d'];return `<div class="section"><h1 class="section-title">Day Trade Monitor</h1><p class="lead">Choose a trigger timeframe and view the current market setup with 1H and 4H context.</p><div class="card"><div class="field"><label>Trigger timeframe</label><select id="dayTf" onchange="state.dayTf=this.value;localStorage.setItem('PMA_DAY_TF',this.value);loadDayTrade()">${tfs.map(x=>`<option ${x===(state.dayTf||'15m')?'selected':''}>${x}</option>`).join('')}</select></div><div class="chips">${Object.keys(markets).map(x=>`<button class="chip ${state.market===x?'active':''}" onclick="state.market='${x}';page('daytrade')">${x}</button>`).join('')}</div><button class="btn alt" onclick="loadDayTrade()">↻ Refresh</button><span id="dayTradeStatus" class="muted" style="display:block;margin-top:8px">Checking market data…</span></div><div id="dayTradeArea" class="grid3" style="margin-top:18px"></div></div>`}
function startDayTrade(){clearInterval(state.dayTradeTimer);loadDayTrade();state.dayTradeTimer=setInterval(loadDayTrade,60000)}
async function loadDayTrade(){const area=document.getElementById('dayTradeArea');if(!area)return;try{const tf=state.dayTf||localStorage.getItem('PMA_DAY_TF')||'15m';const symbols=markets[state.market].slice(0,8).join(',');const x=await apiRetry('/day-trade/plan?market='+encodeURIComponent(state.market)+'&symbols='+encodeURIComponent(symbols)+'&timeframe='+encodeURIComponent(tf));const st=document.getElementById('dayTradeStatus');if(st)st.textContent='Market data updated: '+new Date(x.updated_at).toLocaleTimeString()+(x.errors?.length?' • '+x.errors.length+' symbol(s) unavailable':'');area.innerHTML=(x.setups||[]).map(s=>`<article class="card day-card"><div class="pill">${s.day_trade_state||'WAITING'}</div><h2>${s.symbol}</h2><div class="big">${s.direction||'NO TRADE'}</div><p class="muted">Trigger ${s.timeframe||tf} • Strength ${s.setup_strength??'—'}/100 • ${s.trend_alignment||'—'} context alignment</p><div class="statline"><span>Entry zone</span><b>${s.entry_zone??'Waiting'}</b></div><div class="statline"><span>Stop loss</span><b>${s.stop_loss??'Waiting'}</b></div><div class="statline"><span>Take profit</span><b>${s.take_profit_1??'Waiting'}</b></div><div class="statline"><span>Next setup</span><b>${formatEntryEta(s)}</b></div><p class="muted">${escapeHtml(s.day_trade_reason||'Waiting for confirmation.')}</p></article>`).join('')||'<div class="notice">No verified setup is available right now.</div>'}catch(e){const st=document.getElementById('dayTradeStatus');if(st)st.textContent='Day-trade feed is temporarily unavailable — retrying automatically.';if(!area.innerHTML.trim())area.innerHTML='<div class="notice">Waiting for verified market data. The day-trade monitor will retry automatically.</div>'}}
function progress(){return `<div class="section"><h1 class="section-title">My Progress</h1><p class="lead">Your academy progress is stored with your account. Rank is long-term and is built from referrals, completed tasks, learning progress and consistency.</p><div id="progressArea"><div class="notice">Loading progress…</div></div></div>`}
async function loadProgress(){const el=document.getElementById('progressArea');if(!el)return;try{const [p,l]=await Promise.all([api('/progress'),api('/leaderboard')]);const rankPct=p.rank_progress??0;const dailyDone=new Set(p.completed_daily_task_ids||[]);el.innerHTML=`<div class="grid"><div class="card"><div class="muted">Academy rank</div><div class="big">${escapeHtml(p.rank)}</div><div class="progress-track"><div class="progress-fill" style="width:${rankPct}%"></div></div><p class="muted">${p.next_rank?rankPct+'% toward '+escapeHtml(p.next_rank):'Top rank reached'}</p></div><div class="card"><div class="muted">XP</div><div class="big">${p.xp}</div><p class="muted">Permanent lifetime progress</p></div><div class="card"><div class="muted">Overall progress</div><div class="big">${p.overall_progress}%</div><p class="muted">Learning + tasks + referrals + consistency</p></div><div class="card"><div class="muted">Learning streak</div><div class="big">${p.streak} days</div><p class="muted">Keep building your routine</p></div></div><div class="grid3" style="margin-top:18px"><div class="card"><h3>Learning</h3><div class="big">${p.learning_progress}%</div><p class="muted">${p.completed_lessons}/${p.total_lessons} lessons</p></div><div class="card"><h3>Tasks</h3><div class="big">${p.tasks_progress}%</div><p class="muted">${p.completed_tasks}/${p.total_tasks} permanent tasks</p></div><div class="card"><h3>Referrals</h3><div class="big">${p.qualified_referrals_lifetime}</div><p class="muted">Qualified referrals lifetime</p></div></div><div class="card" style="margin-top:18px"><h2>Daily tasks</h2><p class="muted">These reset each day. Completing them adds to your long-term academy XP and consistency.</p><div class="item-list">${(p.daily_tasks||[]).map(i=>{const done=dailyDone.has(i.id);return `<div class="statline"><span>${escapeHtml(i.title)} <small class="muted">+${i.xp} XP</small></span><button class="btn alt" ${done?'disabled':''} onclick="completeItem('daily-task','${i.id}')">${done?'Completed today':'Complete'}</button></div>`}).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Long-term learning path</h2><p class="muted">Advancement is intentionally slow. The stage ladder is designed for a multi-year academy, not a six-month finish.</p><div class="rank-ladder">${['Beginner I','Beginner II','Beginner III','Beginner IV','Beginner V','Amateur I','Amateur II','Amateur III','Amateur IV','Amateur V','Professional I','Professional II','Professional III','Professional IV','Professional V','Expert I','Expert II','Expert III','Expert IV','Expert V','Master I','Master II','Master III','Master IV','Master V','Pips Master'].map(n=>`<span class="pill ${n===p.rank?'rank-current':''}">${n}</span>`).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Academy tasks</h2><div class="item-list">${(p.tasks||[]).map(i=>`<div class="statline"><span>${escapeHtml(i.title)} <small class="muted">+${i.xp} XP</small></span><button class="btn alt" onclick="completeItem('task','${i.id}')">Complete</button></div>`).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Lessons</h2><div class="item-list">${(p.lessons||[]).map(i=>`<div class="statline"><span>${escapeHtml(i.course)} — ${escapeHtml(i.title)} <small class="muted">+${i.xp} XP</small></span><button class="btn alt" onclick="completeItem('lesson','${i.id}')">Complete</button></div>`).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Academy leaderboard</h2>${(l.leaderboard||[]).slice(0,10).map(i=>`<div class="statline"><span>#${i.rank} ${escapeHtml(i.username)} — ${escapeHtml(i.academy_rank)}</span><b>${i.xp} XP</b></div>`).join('')}</div>`}catch(e){el.innerHTML='<div class="notice">Your progress is temporarily unavailable. Please try again later.</div>'}}
async function completeItem(type,id){try{await api('/progress/'+type,{method:'POST',body:JSON.stringify({item_id:id})});toast('Progress saved');loadProgress()}catch(e){toast(e?.message||'Could not save progress')}}
function referrals(){return `<div class="section"><h1 class="section-title">Referral Progress</h1><p class="lead">Your qualified referrals contribute to your referral rank and permanent academy progress.</p><div class="grid3"><div class="card ref-rank-card"><div class="muted">Referral rank</div><div class="big" id="refRank">Loading…</div><div class="progress-track"><div id="refRankFill" class="progress-fill" style="width:0%"></div></div><p class="muted" id="refRankNote">Loading referral progress…</p></div><div class="card"><div class="muted">Qualified this month</div><div class="big" id="myMonthRefs">—</div><p class="muted">Current qualified referrals.</p></div><div class="card"><div class="muted">Pending referrals</div><div class="big" id="myPendingRefs">—</div><p class="muted">Waiting for qualification.</p></div></div><div class="ref-podium" id="refPodium" style="margin-top:18px"><div class="card podium-second"><div class="podium-medal">🥈</div><h2>2nd Place</h2><div class="big">—</div><div class="muted">qualified referrals</div></div><div class="card podium-first"><div class="podium-medal">🥇</div><h2>1st Place</h2><div class="big">—</div><div class="muted">qualified referrals</div></div><div class="card podium-third"><div class="podium-medal">🥉</div><h2>3rd Place</h2><div class="big">—</div><div class="muted">qualified referrals</div></div></div><div class="card" style="margin-top:18px"><div class="grid3"><div><div class="muted">Qualified referrals lifetime</div><div class="big" id="myTotalRefs">—</div></div><div><div class="muted">Your monthly position</div><div class="big" id="myRefPosition">—</div></div><div><div class="muted">Your monthly score</div><div class="big" id="myRefScore">—</div></div></div></div><div class="card" style="margin-top:18px"><h2>Monthly leaderboard — Top 10</h2><div id="refLeaderboard"><div class="notice">Loading…</div></div><p class="muted" style="margin-top:12px">Only the ten highest monthly referral counts are shown. Your own position remains visible below even if you are outside the top ten.</p></div><div class="card" style="margin-top:18px"><h2>Anti-fake referral rules</h2><p class="muted">Only genuine, verified and active accounts count as qualified referrals. Shared devices or Wi-Fi alone are not automatic proof of manipulation. Referrals made near month-end can finish their normal qualification window after month-end.</p></div></div>`}
async function loadReferrals(){try{const x=await api('/referrals');document.getElementById('myMonthRefs').textContent=x.month_qualified??0;document.getElementById('myPendingRefs').textContent=x.pending??0;document.getElementById('myTotalRefs').textContent=x.qualified_total??0;document.getElementById('myRefPosition').textContent=x.position?('#'+x.position):'—';document.getElementById('myRefScore').textContent=x.month_qualified??0;document.getElementById('refRank').textContent=x.referral_rank||'—';document.getElementById('refRankFill').style.width=(x.referral_rank_progress??0)+'%';document.getElementById('refRankNote').textContent=x.next_referral_rank?`${x.referral_rank_progress}% toward ${x.next_referral_rank}`:'Top referral rank reached';const rows=x.monthly_leaderboard||[];const podium=[rows.find(r=>r.rank===2),rows.find(r=>r.rank===1),rows.find(r=>r.rank===3)];['podium-second','podium-first','podium-third'].forEach((cls,i)=>{const card=document.querySelector('.'+cls);const r=podium[i];if(card&&r){card.querySelector('h2').textContent=(i===0?'2nd':i===1?'1st':'3rd')+' Place — '+r.username;card.querySelector('.big').textContent=r.qualified}});document.getElementById('refLeaderboard').innerHTML=rows.map(r=>`<div class="statline"><span>#${r.rank} ${escapeHtml(r.username)}</span><b>${r.qualified}</b></div>`).join('')||'<p class="muted">No qualified referrals recorded yet this month.</p>'}catch(e){const el=document.getElementById('refLeaderboard');if(el)el.innerHTML='<div class="notice">Referral information is temporarily unavailable.</div>'}}
function community(){return `<div class="section"><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><div><h1 class="section-title">Community</h1><p class="muted">Share questions, lessons, market ideas and media with the group.</p></div><span id="lockState" class="lock">🔓 Open</span></div><div id="messages" class="msgbox"></div><div class="filters"><input id="msgInput" class="search" placeholder="Write a message..."><label class="file-btn">📷 Photo / 🎥 Video<input id="mediaInput" type="file" accept="image/*,video/*" class="hidden" onchange="previewMessageMedia(event)"></label><button class="btn" onclick="sendMsg()">Send</button></div><div id="mediaPreview" class="media-preview"></div><p class="muted" style="font-size:12px">You can attach one photo or video.</p></div></div>`}
async function loadMessages(){try{const x=await api('/community/messages');renderMessages(x.messages||[]);lockState.textContent=x.locked?'🔒 Locked':'🔓 Open'}catch{renderMessages([]);lockState.textContent='🔓 Open'}}
function renderMessages(list){messages.innerHTML=list.map(m=>`<div class="msg ${m.username===state.user.username?'right':''}"><b>${escapeHtml(m.username||'Member')}</b> <span class="muted">${escapeHtml(m.pma_id||'')}</span><br>${escapeHtml(m.text||'')}${m.media_data?(m.media_type||'').startsWith('video')?`<video class="message-media" controls src="${m.media_data}"></video>`:`<img class="message-media" src="${m.media_data}" alt="Shared media">`:''}<small class="muted"> ${escapeHtml(m.time||'just now')}</small></div>`).join('')||'<p class="muted">No messages yet.</p>'}
function previewMessageMedia(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Media must be under 5MB');e.target.value='';return}const r=new FileReader();r.onload=()=>{state.pendingMedia={data:r.result,type:file.type,name:file.name};mediaPreview.innerHTML=file.type.startsWith('video')?`<video controls src="${r.result}"></video>`:`<img src="${r.result}" alt="Selected media">`;};r.readAsDataURL(file)}
async function sendMsg(){const text=msgInput.value.trim();const media=state.pendingMedia;if(!text&&!media)return;const payload={text,media_data:media?.data||'',media_type:media?.type||''};try{await api('/community/messages',{method:'POST',body:JSON.stringify(payload)});addNotification('Community message sent','Your message was posted.');}catch{toast('Message could not be sent right now.')}msgInput.value='';state.pendingMedia=null;mediaPreview.innerHTML='';if(window.loadMessages)loadMessages()}
function escapeHtml(s){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function profile(){const u=state.user;const pic=u.profile_picture||'assets/images/profile-placeholder.svg';const link=location.origin+location.pathname+'?ref='+encodeURIComponent(u.referral_code||'');const adminBlock=(u.role==='admin'&&state.serverVerified)?`<div class="card admin-panel"><h2>Admin Controls</h2><p class="muted">Administrator controls are available on this account.</p><div id="adminStatsInline" class="grid3"><div class="notice">Checking admin status…</div></div><div class="filters admin-status"><button class="btn" onclick="toggleLock()">Lock / Unlock Community</button><button class="btn alt" onclick="loadAdminStats()">Refresh admin status</button></div><div id="adminFeedbackInline" style="margin-top:14px"></div></div>`:'';return `<div class="section"><h1 class="section-title">My Profile</h1><p class="lead">Manage your personal details, referral link and academy information.</p><div class="profile-layout"><div class="card profile-photo-card"><img id="profileAvatar" class="avatar" src="${pic}" alt="Profile picture"><div class="profile-actions"><label class="btn alt" style="cursor:pointer">Change picture<input id="picInput" type="file" accept="image/*" class="hidden" onchange="previewPicture(event)"></label><button class="btn ghost" onclick="removePicture()">Remove</button></div><p class="muted" style="font-size:12px">Your profile picture is part of your account profile.</p></div><div class="card"><h2>Personal details</h2><div class="profile-form"><div class="field"><label>Full Name</label><input id="pfName" value="${escapeAttr(u.full_name||'')}"></div><div class="field"><label>Username</label><input id="pfUser" value="${escapeAttr(u.username||'')}"></div><div class="field"><label>Phone Number</label><input id="pfPhone" value="${escapeAttr(u.phone||'')}" placeholder="Optional"></div><div class="field"><label>Date of Birth</label><input id="pfDob" type="date" value="${escapeAttr(u.dob||'')}"></div><div class="field full"><label>Email</label><input class="readonly" value="${escapeAttr(u.email||'')}" readonly></div><div class="field"><label>PMA User ID</label><input class="readonly" value="${escapeAttr(u.pma_id||'')}" readonly></div><div class="field"><label>Account Role</label><input class="readonly" value="${u.role==='admin'?'Administrator':'Member'}" readonly></div></div><button class="btn" onclick="saveProfile()">Save profile</button><div class="divider"></div><h3>Change password</h3><div class="profile-form"><div class="field"><label>New Password</label><div class="password-wrap"><input id="newPass" type="password"><button class="eye-btn" type="button" onclick="togglePassword('newPass',this)">👁️</button></div></div><div class="field"><label>Confirm New Password</label><div class="password-wrap"><input id="newPass2" type="password"><button class="eye-btn" type="button" onclick="togglePassword('newPass2',this)">👁️</button></div></div></div><button class="btn alt" onclick="changePassword()">Update password</button></div></div>${adminBlock}<div class="grid3" style="margin-top:18px"><div class="card color-card"><h3>Your referral link</h3><div class="big">${escapeHtml(u.referral_code||'')}</div><p class="muted">Share this unique referral link with people you know.</p><div class="copy-row"><input class="search ref-link-field" value="${escapeAttr(link)}" readonly id="refLink" title="${escapeAttr(link)}"><button class="btn alt" onclick="copyReferral(document.getElementById('refLink').value)">Copy referral link</button></div></div><div class="card color-card"><h3>Account progress</h3><p class="muted">Your permanent academy level, XP, tasks, learning and referrals are stored with your account.</p><button class="btn alt" onclick="page('progress')">View My Progress</button></div><div class="card color-card"><h3>Feedback</h3><p class="muted">Tell us what is working, what is missing and what should be improved.</p><button class="btn alt" onclick="page('feedback')">Send Feedback</button></div></div></div>`}
function escapeAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
async function persistProfile(){try{if(!localStorage.getItem('PMA_TOKEN'))return false;const x=await api('/auth/profile',{method:'PUT',body:JSON.stringify({full_name:state.user.full_name,username:state.user.username,phone:state.user.phone,dob:state.user.dob,profile_picture:state.user.profile_picture||''})});if(x.user){state.user={...state.user,...x.user};saveLocalUser(state.user);return true}}catch(e){}return false}
function previewPicture(e){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Please choose an image under 2MB');return}const r=new FileReader();r.onload=async()=>{state.user.profile_picture=r.result;saveLocalUser(state.user);const avatar=document.getElementById('profileAvatar');if(avatar)avatar.src=r.result;const saved=await persistProfile();addNotification('Profile picture updated',saved?'Your new profile picture was saved to your account.':'Your new profile picture was saved on this browser.','account');toast(saved?'Profile picture saved':'Profile picture saved locally')};r.readAsDataURL(file)}
async function removePicture(){state.user.profile_picture='';saveLocalUser(state.user);const saved=await persistProfile();page('profile');addNotification('Profile picture removed',saved?'Your profile picture was removed from your account.':'Your profile picture was removed on this browser.','account');toast('Profile picture removed')}
async function saveProfile(){state.user.full_name=pfName.value.trim();state.user.username=pfUser.value.trim();state.user.phone=pfPhone.value.trim();state.user.dob=pfDob.value;saveLocalUser(state.user);const saved=await persistProfile();userMini.textContent='@'+state.user.username;addNotification('Profile saved',saved?'Your profile details were saved to your account.':'Your profile details were saved on this browser.','account');toast(saved?'Profile saved successfully':'Profile saved locally');const pos=document.getElementById('screen')?.scrollTop||0;page('profile',false);requestAnimationFrame(()=>{document.getElementById('screen').scrollTop=pos})}
async function changePassword(){if(newPass.value.length<8){toast('Password must be at least 8 characters');return}if(newPass.value!==newPass2.value){toast('Passwords do not match');return}try{await api('/auth/password',{method:'PUT',body:JSON.stringify({password:newPass.value})});toast('Password changed successfully');addNotification('Password updated','Your password was updated successfully.','security')}catch(e){toast('Password could not be saved to the account.')}newPass.value='';newPass2.value=''}
async function copyText(t){return copyReferral(t)}
async function copyReferral(t){let ok=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(String(t));ok=true}}catch(e){}if(!ok){const ta=document.createElement('textarea');ta.value=t;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();try{ok=document.execCommand('copy')}catch(e){}ta.remove()}if(ok){toast('Referral link copied');addNotification('Referral link copied','Your referral link is ready to share.','referral')}else{const input=document.getElementById('refLink');if(input){input.focus();input.select()}toast('Copy failed — the link is selected for you')}}
function feedback(){return `<div class="section"><div class="card"><h1 class="section-title">Feedback</h1><p class="lead">Tell us what you like, what is not working, or what you want added to Pips Master Academy.</p><div class="field"><label>Feedback type</label><select id="fbCategory"><option>General</option><option>Bug report</option><option>Feature request</option><option>Scanner / Day Trade</option><option>Learning</option><option>Community</option><option>Referral system</option></select></div><div class="field"><label>Rating</label><div class="feedback-rating">${[1,2,3,4,5].map(n=>`<button type="button" class="rating-choice ${n===5?'active':''}" data-rating="${n}" onclick="selectFeedbackRating(${n})">${n} ★</button>`).join('')}</div><input type="hidden" id="fbRating" value="5"></div><div class="field"><label>Your feedback</label><textarea id="fbMessage" placeholder="Tell us what happened or what you would like us to improve…"></textarea></div><button class="btn" onclick="submitFeedback()">Send Feedback</button><div id="fbMsg" class="form-msg"></div></div><div class="card" style="margin-top:18px"><h2>Your previous feedback</h2><div id="myFeedback"><div class="notice">Loading…</div></div></div></div>`}
function selectFeedbackRating(n){document.getElementById('fbRating').value=n;document.querySelectorAll('.rating-choice').forEach(b=>b.classList.toggle('active',Number(b.dataset.rating)===n))}
async function submitFeedback(){const message=fbMessage.value.trim();if(!message){fbMsg.textContent='Please write your feedback first.';fbMsg.className='form-msg error';return}try{await api('/feedback',{method:'POST',body:JSON.stringify({category:fbCategory.value,rating:Number(fbRating.value),message})});fbMessage.value='';fbMsg.textContent='Feedback sent successfully.';fbMsg.className='form-msg ok';addNotification('Feedback received','Your feedback was saved successfully.','feedback');loadMyFeedback()}catch(e){fbMsg.textContent=e?.message||'Feedback could not be saved.';fbMsg.className='form-msg error'}}
async function loadMyFeedback(){const el=document.getElementById('myFeedback');if(!el)return;try{const x=await api('/feedback');el.innerHTML=(x.feedback||[]).map(f=>`<div class="notification-item"><b>${escapeHtml(f.category)} • ${f.rating}★</b><p class="muted" style="margin:6px 0">${escapeHtml(f.message)}</p><small class="muted">${escapeHtml(f.time)} • ${escapeHtml(f.status)}</small></div>`).join('')||'<p class="muted">No feedback sent yet.</p>'}catch(e){el.innerHTML='<div class="notice">Your feedback history could not be loaded.</div>'}}

function about(){const reviews=[['Amina Yusuf','https://randomuser.me/api/portraits/women/44.jpg','5.0','The layout makes the learning process feel much more organised. I can move from market education to analysis and then to the calculator without feeling lost.','5'],['Daniel Okoro','https://randomuser.me/api/portraits/men/32.jpg','4.8','I like how the academy brings several useful ideas together. The explanations are short enough to understand while still giving me a clear direction for what to study next.','5'],['Grace Mensah','https://randomuser.me/api/portraits/women/68.jpg','4.7','The community section gives the platform a more active feel, and having profile controls and referral tools in one place makes the experience easier to manage.','5'],['Samuel Adeyemi','https://randomuser.me/api/portraits/men/46.jpg','4.5','The design feels modern and the market sections are easy to move through. I especially like the focus on preparation, risk and understanding the market instead of chasing random entries.','4'],['Chiamaka Eze','https://randomuser.me/api/portraits/women/65.jpg','4.2','There is a lot to explore, but the sections are clearly separated. The academy feels like a useful place to keep learning notes, market ideas and community discussions together.','4'],['David Mensah','https://randomuser.me/api/portraits/men/75.jpg','4.6','The workspace is easy to move through and the market tools are presented in a way that keeps the important information visible.','5'],['Sarah Bello','https://randomuser.me/api/portraits/women/49.jpg','4.4','I like the balance between the academy material, account tools and community area. It feels much more like one complete workspace.','4']];return `<div class="section"><h1 class="section-title">About Pips Master Academy</h1><p class="lead">Pips Master Academy is built around a simple idea: make market learning, analysis, planning and community interaction easier to access from one organised workspace. The platform is designed to keep the learning process practical, visually clear and focused on building better habits over time.</p><div class="grid3"><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1200&q=85"><h3>Market structure</h3><p class="muted">Study trend direction, support and resistance, supply and demand, momentum and candle confirmation as connected parts of a bigger picture.</p></div><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=1200&q=85"><h3>Analysis with context</h3><p class="muted">Instead of relying on one candle, compare multiple timeframes and look for structure before considering an opportunity.</p></div><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85"><h3>Risk awareness</h3><p class="muted">A setup is only one part of a trading plan. Position size, stop placement and discipline matter too.</p></div></div><div class="card" style="margin-top:18px"><h2>Forex in a few words</h2><p class="lead">Forex is the market where currencies are traded in pairs, such as EUR/USD or GBP/JPY. Traders compare the strength of one currency against another and may study trends, market structure, economic news, support and resistance, and risk before making a decision. Prices can move quickly, so learning and risk control are important.</p></div><div class="card" style="margin-top:18px"><h2>Contact Us</h2><p class="muted">Need help with your account, profile, referral link or community access? Contact Pips Master Academy customer service directly on Telegram.</p><a class="btn" href="https://t.me/Zinolee6" target="_blank" rel="noopener">💬 Telegram Customer Service</a></div><div class="card photo-section" style="margin-top:18px"><h2>Inside the learning workspace</h2><p class="muted">Different visual scenes keep the academy from feeling like one repeated green-and-black pattern.</p><div class="image-band"><img src="https://images.unsplash.com/photo-1518186285589-2f7649de83e0?auto=format&fit=crop&w=900&q=85" alt="Market research workspace"><img src="https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=900&q=85" alt="Data dashboard"><img src="https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=900&q=85" alt="Analytics screen"><img src="https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=900&q=85" alt="Modern workspace"></div></div><div class="card" style="margin-top:18px"><h2>Member Reviews</h2><p class="muted">Sample design testimonials — not verified current-member statements.</p><div class="rating-bars"><div class="rating-line"><span>5 ★</span><div class="rating-track"><div class="rating-fill fill5"></div></div><b>72%</b></div><div class="rating-line"><span>4 ★</span><div class="rating-track"><div class="rating-fill fill4"></div></div><b>18%</b></div><div class="rating-line"><span>3 ★</span><div class="rating-track"><div class="rating-fill fill3"></div></div><b>6%</b></div><div class="rating-line"><span>2 ★</span><div class="rating-track"><div class="rating-fill fill2"></div></div><b>3%</b></div><div class="rating-line"><span>1 ★</span><div class="rating-track"><div class="rating-fill fill1"></div></div><b>1%</b></div></div></div><div class="review-grid">${reviews.map(r=>`<article class="card review-card color-card"><div class="review-head"><img class="review-avatar" src="${r[1]}" alt="${r[0]}"><div><strong>${r[0]}</strong><div class="star">★★★★★ <span class="rating-number">${r[2]}</span></div></div></div><p class="quote">“${r[3]}”</p><p class="muted" style="font-size:12px">Sample testimonial • ${r[4]} star rating highlighted</p></article>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Questions & Answers</h2><p><b>Are signals guaranteed?</b><br><span class="muted">No. Market conditions change and any automated setup estimate depends on the quality and availability of connected data.</span></p><p><b>Can I edit my profile?</b><br><span class="muted">Yes. Personal details and your profile picture can be changed and saved.</span></p><p><b>How do I contact support?</b><br><span class="muted">Use the Telegram Customer Service button above.</span></p></div><div class="footer-note">Pips Master Academy • Learn first. Analyse clearly. Manage risk responsibly.</div></div>`}
function admin(){page('profile');return ''}
async function toggleLock(){try{const status=await api('/admin/status');if(!status.is_admin)throw Error('Administrator verification failed.');const x=await api('/admin/community/toggle',{method:'POST'});toast(x.locked?'Community locked':'Community opened');loadAdminStats();loadMessages()}catch(e){toast(e?.message||'Admin access required')}}
async function loadAdminStats(){const el=document.getElementById('adminStatsInline');if(!el)return;try{if(!state.serverVerified||state.user?.role!=='admin')throw Error('Admin access denied');const [status,x]=await Promise.all([api('/admin/status'),api('/admin/stats')]);el.innerHTML=`<div class="card"><div class="muted">Admin verification</div><div class="big">✅ Verified</div><p class="muted">${escapeHtml(status.email||state.user.email)}</p></div><div class="card"><div class="muted">Total users</div><div class="big">${x.total_users}</div></div><div class="card"><div class="muted">Active in 7 days</div><div class="big">${x.active_7d}</div></div><div class="card"><div class="muted">Community</div><div class="big">${x.community_locked?'🔒 Locked':'🔓 Open'}</div></div>`;const fb=document.getElementById('adminFeedbackInline');if(fb)fb.innerHTML=x.feedback_new?`<div class="notice">📩 ${x.feedback_new} new feedback item${x.feedback_new===1?'':'s'}.</div>`:'<div class="save-state">No new feedback yet.</div>'}catch(e){el.innerHTML=''}}
async function syncBackendProfile(){if(!localStorage.getItem('PMA_TOKEN'))return;try{const x=await api('/auth/profile');if(x.user){state.user={...state.user,...x.user};saveLocalUser(state.user);userMini.textContent='@'+state.user.username}}catch(e){}}
async function enableBrowserAlerts(){if(!('Notification' in window)){toast('This browser does not support notifications');return false}try{const permission=await Notification.requestPermission();state.browserAlertsReady=permission==='granted';toast(state.browserAlertsReady?'Browser alerts enabled':'Browser alerts were not enabled');return state.browserAlertsReady}catch(e){toast('Browser notification permission could not be requested');return false}}
function browserNotify(n){if(!('Notification' in window)||Notification.permission!=='granted')return;try{const note=new Notification(n.title||'Pips Master Academy',{body:n.text||'',tag:'pma-'+(n.id||Date.now())});note.onclick=()=>{window.focus();page(notificationTarget(n));note.close()}}catch(e){}}
function notificationTarget(n){return n.target_page||({referral:'referrals',community:'community',task:'progress',learning:'progress',signal:'signals',account:'profile',security:'profile',feedback:'feedback'}[n.type]||'home')}
function mergeNotificationHistory(list){const history=getNotificationHistory();const byKey=new Map(history.map(n=>[String(n.server_id||n.id),n]));for(const n of list){const k=String(n.server_id||n.id);if(!byKey.has(k)){history.unshift(n);byKey.set(k,n)}}const trimmed=history.slice(0,250);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(trimmed));return trimmed}
function addInboxNotification(n){const dismissed=new Set(readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]).map(String));if(dismissed.has(String(n.server_id||n.id)))return;const inbox=getNotificationInbox();inbox.unshift(n);localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox.slice(0,60)))}
async function syncBackendNotifications(){try{const x=await api('/notifications');const incoming=(x.notifications||[]).map(n=>({...n,server_id:n.id}));const previousIds=new Set(getNotificationHistory().map(n=>String(n.server_id||n.id)));mergeNotificationHistory(incoming);for(const n of incoming){if(!previousIds.has(String(n.server_id||n.id))){addInboxNotification(n);browserNotify(n)}}updateNotifBadge()}catch(e){}}
async function openNotification(index){const arr=getNotificationInbox();const n=arr[index];if(!n)return;const history=getNotificationHistory().map(x=>String(x.server_id||x.id)===String(n.server_id||n.id)?{...x,read:true}:x);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(arr.filter((_,i)=>i!==index)));updateNotifBadge();if(n.server_id){try{await api('/notifications/read-one',{method:'POST',body:JSON.stringify({notification_id:Number(n.server_id)})})}catch(e){}}document.getElementById('notifPanel')?.classList.add('hidden');page(notificationTarget(n))}
function clearTopNotifications(){const inbox=getNotificationInbox();const ids=readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]);const all=[...new Set([...ids,...inbox.map(n=>String(n.server_id||n.id))])];localStorage.setItem('PMA_NOTIFICATION_DISMISSED_IDS',JSON.stringify(all));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify([]));updateNotifBadge();toggleNotifications()}
function toggleNotifications(){const panel=document.getElementById('notifPanel');if(!panel)return;if(!panel.classList.contains('hidden')){panel.classList.add('hidden');return}const arr=getNotificationInbox();panel.innerHTML='<div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><h3 style="margin:0">Recent notifications</h3><button class="btn alt" onclick="enableBrowserAlerts()">🔔 Browser alerts</button></div>'+(arr.length?arr.slice(0,12).map((n,i)=>`<button class="notification-item ${n.read?'':'unread'}" onclick="openNotification(${i})" style="width:100%;text-align:left;color:inherit;cursor:pointer"><b>${escapeHtml(n.title)}</b><p style="margin:5px 0" class="muted">${escapeHtml(n.text)}</p><small class="muted">${escapeHtml(n.time||'')}</small></button>`).join(''):'<div class="notice" style="margin-top:10px">No new notifications in the top panel.</div>')+'<div style="display:flex;gap:8px;margin-top:10px"><button class="btn alt" onclick="page(\'notifications\')">View all</button><button class="btn alt clear-notifications" onclick="clearTopNotifications()">Clear</button></div>';panel.classList.remove('hidden')}
async function markNotificationsRead(){const history=getNotificationHistory().map(n=>({...n,read:true}));const inbox=getNotificationInbox().map(n=>({...n,read:true}));localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox));updateNotifBadge();try{await api('/notifications/read')}catch(e){}}
function notificationCategories(){return ['All','Referrals','Tasks & Learning','Community','Signals','Account','Feedback']}
function notificationMatches(n,cat){if(cat==='All')return true;if(cat==='Referrals')return n.type==='referral';if(cat==='Tasks & Learning')return ['task','learning'].includes(n.type);if(cat==='Community')return n.type==='community';if(cat==='Signals')return n.type==='signal';if(cat==='Feedback')return n.type==='feedback';if(cat==='Account')return ['account','security','info'].includes(n.type);return true}
async function loadNotificationsPage(){const el=document.getElementById('notificationsArea');if(!el)return;el.innerHTML='<div class="notice">Loading notification history…</div>';try{await syncBackendNotifications();const data=getNotificationHistory();const cat=state.notificationCategory||'All';const filtered=data.filter(n=>notificationMatches(n,cat));el.innerHTML=`<div class="card"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h2 style="margin:0">Notification history</h2><p class="muted" style="margin:6px 0 0">Your history stays here even when you clear the small top-right notification panel.</p></div><div class="live-badge"><span class="live-dot"></span>Updated</div></div><div class="notification-tabs">${notificationCategories().map(c=>`<button class="notification-category ${c===cat?'active':''}" onclick="state.notificationCategory='${c}';loadNotificationsPage()">${c}</button>`).join('')}</div><div class="filters"><button class="btn alt" onclick="markNotificationsRead();loadNotificationsPage()">Mark all as read</button><button class="btn alt" onclick="enableBrowserAlerts()">Enable browser alerts</button></div><div class="notification-history-grid">${filtered.map(n=>`<button class="notification-item ${n.read?'':'unread'}" onclick="openHistoryNotification(${JSON.stringify(String(n.server_id||n.id))})" style="width:100%;text-align:left;color:inherit;cursor:pointer"><b>${escapeHtml(n.title)}</b><p style="margin:5px 0" class="muted">${escapeHtml(n.text)}</p><small class="muted">${escapeHtml(n.time||'')}</small><div style="font-size:11px;color:var(--mint);margin-top:5px">Open ${escapeHtml(notificationTarget(n))} →</div></button>`).join('')||'<div class="notice">No notifications in this category yet.</div>'}</div></div>`}catch(e){el.innerHTML='<div class="notice">Notification history is temporarily unavailable.</div>'}}
function openHistoryNotification(id){const history=getNotificationHistory();const idx=history.findIndex(n=>String(n.server_id||n.id)===String(id));if(idx<0)return;const n=history[idx];history[idx]={...n,read:true};localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history));updateNotifBadge();if(n.server_id)api('/notifications/read-one',{method:'POST',body:JSON.stringify({notification_id:Number(n.server_id)})}).catch(()=>{});page(notificationTarget(n))}
function notifications(){return `<div class="section"><h1 class="section-title">Notifications</h1><p class="lead">Keep a full history of referrals, learning, tasks, community, scanner and account notifications.</p><div id="notificationsArea"><div class="notice">Loading…</div></div></div>`}
function startNotificationPolling(){clearInterval(state.notifTimer);state.notifTimer=setInterval(()=>{if(state.user)syncBackendNotifications()},10000)}
function toast(msg){toastEl.textContent=msg;toastEl.classList.remove('hidden');clearTimeout(window.tt);window.tt=setTimeout(()=>toastEl.classList.add('hidden'),2600)}
const toastEl=document.getElementById('toast');
function logout(){if(confirm('Do you really want to log out?')){api('/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false;addNotification('Signed out','You logged out successfully.','security');show('welcome')}}
async function bootstrapPMA(){migrateNotifications();state.notif=getNotificationHistory();updateNotifBadge();const token=localStorage.getItem('PMA_TOKEN');if(token){try{const x=await apiRetry('/auth/profile',{},1);state.user=x.user;state.serverVerified=true;saveLocalUser(state.user);enterApp(false);return}catch(e){localStorage.removeItem('PMA_TOKEN');state.serverVerified=false}}if(state.ref){show('signup')}else{show('welcome')}}
applyTheme();
bootstrapPMA();
document.addEventListener('keydown',e=>{if(e.key==='Enter'){if(document.getElementById('login')?.classList.contains('active'))login();else if(document.getElementById('signup')?.classList.contains('active'))signup()}});
window.addEventListener('beforeunload',()=>{const sc=document.getElementById('screen');if(state.user){localStorage.setItem('PMA_CURRENT_PAGE',state.page);localStorage.setItem('PMA_SCROLL_'+state.page);localStorage.setItem('PMA_MARKET',state.market);localStorage.setItem('PMA_SYMBOL',state.symbol)}});
async function softRefreshCurrentPage(){const sc=document.getElementById('screen');const pos=sc?.scrollTop||0;try{if(state.page==='signals')await scanMarket();else if(state.page==='daytrade')await loadDayTrade();else if(state.page==='progress')await loadProgress();else if(state.page==='referrals')await loadReferrals();else if(state.page==='community')await loadMessages();else if(state.page==='profile'){await syncBackendProfile();if(state.user?.role==='admin')await loadAdminStats()}else if(state.page==='feedback')await loadMyFeedback();else if(state.page==='notifications')await loadNotificationsPage();else page(state.page,true)}finally{requestAnimationFrame(()=>{const s=document.getElementById('screen');if(s)s.scrollTop=pos})}}
(function(){let startY=null,pulling=false;const badge=document.getElementById('pullRefresh');document.addEventListener('touchstart',e=>{const t=e.touches[0];if(!t||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName))return;const sc=document.getElementById('screen');if(sc&&sc.scrollTop<=0){startY=t.clientY;pulling=true}},{passive:true});document.addEventListener('touchmove',e=>{if(!pulling||startY==null)return;const t=e.touches[0];const d=t.clientY-startY;if(d>10){const amount=Math.min(80,d*.7);badge.style.transform=`translateX(-50%) translateY(${Math.max(-20,amount-80)}px)`;badge.style.opacity=String(Math.min(1,d/90))}},{passive:true});document.addEventListener('touchend',async e=>{if(!pulling)return;const t=e.changedTouches[0];const d=(t?.clientY||0)-startY;pulling=false;startY=null;if(d>90){badge.classList.add('show');badge.textContent='↻ Updating…';await softRefreshCurrentPage();setTimeout(()=>{badge.classList.remove('show');badge.style.opacity='0';badge.style.transform='translateX(-50%) translateY(-80px)'},500)}else{badge.classList.remove('show');badge.style.opacity='0';badge.style.transform='translateX(-50%) translateY(-80px)'}})})();
